import java.util.ArrayList;
import java.util.List;

public class MemoryLeakLab {
    private static final List<byte[]> CACHE = new ArrayList<>();

    public static void main(String[] args) throws InterruptedException {
        int count = 0;
        while (true) {
            CACHE.add(new byte[1024 * 1024]);
            System.out.printf("Blocos retidos: %d MB%n", ++count);
            Thread.sleep(100);
        }
    }
}

// Com região G1 de 1 MiB:
CACHE.add(new byte[1024 * 1024]); // Humongous
CACHE.add(new byte[100 * 1024]);  // Alocação comum

import java.util.ArrayList;
import java.util.List;

public class MemoryLeakLab {
    private static final List<byte[]> CACHE = new ArrayList<>();

    public static void main(String[] args) throws InterruptedException {
        for (int i = 0; i < 100; i++) {
            CACHE.add(new byte[100 * 1024]);
            if ((i + 1) % 2 == 0) CACHE.clear();
            System.out.printf("Iteração %d | Retidos: %d%n", i + 1, CACHE.size());
            Thread.sleep(100);
        }
    }
}

